          backgroundColor: '#f8fafc',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <Box
          component=\"img\"
          src={articleImage}
          alt={article.title}
          sx={{
            width: '100%',
            height: 'auto',
