                          label={mainFeaturedArticle.categoryName || 'LA BÀN SỰ NGHIỆP'}
                          size=\"small\"
                          sx={{
                            alignSelf: 'flex-start',
                            height: 24,
                            fontSize: '0.7rem',
                            fontWeight: 800,
                            bgcolor: 'rgba(255, 255, 255, 0.20)',
                            color: '#ffffff',
                            mb: 1.5,
                          }}
                        />
                        <Typography variant=\"h5\" fontWeight={800} sx={{ lineHeight: 1.25, mb: 1.5 }}>
                          {mainFeaturedArticle.title}
                        </Typography>
                        <Typography variant=\"body2\" sx={{ color: 'rgba(255,255,255,0.88)', lineHeight: 1.6, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
                          {mainFeaturedArticle.excerpt}
                        </Typography>
                      </Box>
                    </CardActionArea>
                  </Card>
                </Grid>
              )}
            </Grid>
          )}
        </Box>

        {/* ── Latest Articles Section with Filter Tabs ────────────────────────── */}
        <Box sx={{ mb: 6 }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} justifyContent=\"space-between\" alignItems={{ sm: 'center' }} spacing={2} sx={{ mb: 3 }}>
            <Typography variant=\"h5\" fontWeight={800} color=\"#0f172a\" sx={{ letterSpacing: '-0.01em' }}>
              Bài viết mới nhất
            </Typography>

            {/* Category Filter Pills */}
            <Stack direction=\"row\" spacing={1} flexWrap=\"wrap\" sx={{ gap: 1 }}>
              <Chip
                label=\"TẤT CẢ\"
                clickable
                onClick={() => handleSelectCategory('all')}
                sx={{
                  fontWeight: 800,
                  fontSize: '0.75rem',
                  bgcolor: activeCategorySlug === 'all' ? '#e11d48' : 'transparent',
                  color: activeCategorySlug === 'all' ? '#ffffff' : '#64748b',
                  border: '1px solid',
                  borderColor: activeCategorySlug === 'all' ? '#e11d48' : '#cbd5e1',
                  '&:hover': { bgcolor: activeCategorySlug === 'all' ? '#be123c' : 'rgba(225, 29, 72, 0.08)' },
                }}
              />
              {categories.slice(0, 5).map((cat) => {
                const isSelected = activeCategorySlug === cat.slug;
                return (
                  <Chip
                    key={cat.id}
                    label={cat.name.toUpperCase()}
                    clickable
                    onClick={() => handleSelectCategory(cat.slug)}
                    sx={{
                      fontWeight: 800,
                      fontSize: '0.75rem',
                      bgcolor: isSelected ? '#e11d48' : 'transparent',
                      color: isSelected ? '#ffffff' : '#64748b',
                      border: '1px solid',
                      borderColor: isSelected ? '#e11d48' : '#cbd5e1',
                      '&:hover': { bgcolor: isSelected ? '#be123c' : 'rgba(225, 29, 72, 0.08)' },
                    }}
                  />
                );
              })}
            </Stack>
          </Stack>

          {/* 3-Column Articles Grid */}
          {isLoading ? (
            <Grid container spacing={3}>
              {Array.from({ length: 6 }).map((_, idx) => (
                <Grid key={idx} size={{ xs: 12, sm: 6, md: 4 }}>
                  <Skeleton variant=\"rectangular\" height={260} sx={{ borderRadius: 3 }} />
                </Grid>
              ))}
            </Grid>
          ) : displayLatestArticles.length === 0 ? (
            <NoDataCard title=\"Không tìm thấy bài viết\" content=\"Hiện chưa có bài viết thuộc danh mục này.\" />
          ) : (
            <Grid container spacing={3}>
              {displayLatestArticles.map((article) => {
                const articleHref = localizeRoutePath(`/${formatRoute(ROUTES.JOB_SEEKER.NEWS_DETAIL, article.slug)}`, i18n.language);
                const articleTimestamp = article.publishedAt || article.createAt || article.updateAt;
                const publishedAgo = articleTimestamp ? dayjs(articleTimestamp).fromNow() : 'Mới cập nhật';

                return (
                  <Grid key={article.id} size={{ xs: 12, sm: 6, md: 4 }}>
                    <Card
                      elevation={0}
                      sx={{
                        height: '100%',
                        borderRadius: 3,
                        border: '1px solid #e2e8f0',
                        backgroundColor: '#ffffff',
                        display: 'flex',
                        flexDirection: 'column',
                        transition: 'all 0.25s ease',
                        '&:hover': {
                          transform: 'translateY(-4px)',
                          boxShadow: '0 16px 36px rgba(15, 23, 42, 0.10)',
                          borderColor: '#e11d48',
                        },
                      }}
                    >
                      <CardActionArea
                        component={Link}
                        href={articleHref}
                        sx={{ height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'stretch' }}
                      >
                        <CardMedia
                          component=\"img\"
                          image={getArticleImage(article)}
                          alt={article.title}
                          sx={{ height: 190, objectFit: 'cover' }}
                        />
                        <CardContent sx={{ p: 2.5, flex: 1, display: 'flex', flexDirection: 'column' }}>
                          <Typography
                            variant=\"h6\"
                            fontWeight={700}
                            sx={{
                              color: '#0f172a',
                              fontSize: '1rem',
                              lineHeight: 1.35,
                              mb: 1.5,
                              display: '-webkit-box',
                              WebkitLineClamp: 2,
                              WebkitBoxOrient: 'vertical',
                              overflow: 'hidden',
                              '&:hover': { color: '#e11d48' },
                            }}
                          >
                            {article.title}
                          </Typography>
                          <Typography
                            variant=\"body2\"
                            sx={{
                              color: '#64748b',
                              fontSize: '0.825rem',
                              lineHeight: 1.5,
                              mb: 2,
                              display: '-webkit-box',
                              WebkitLineClamp: 2,
                              WebkitBoxOrient: 'vertical',
                              overflow: 'hidden',
                            }}
                          >
                            {article.excerpt}
                          </Typography>
                          <Typography variant=\"caption\" sx={{ color: '#94a3b8', mt: 'auto', fontWeight: 600 }}>
                            Bởi {article.authorName || 'Admin'} • {publishedAgo}
                          </Typography>
                        </CardContent>
                      </CardActionArea>
                    </Card>
                  </Grid>
                );
              })}
            </Grid>
          )}

          {/* Pagination */}
          {pageCount > 1 && (
            <Stack direction=\"row\" justifyContent=\"center\" sx={{ mt: 5 }}>
              <Pagination
                count={pageCount}
                page={page}
                onChange={(_, nextPage) => setPage(nextPage)}
                color=\"primary\"
                sx={{
                  '& .MuiPaginationItem-root.Mui-selected': {
                    bgcolor: '#e11d48',
                    color: '#ffffff',
                  },
                }}
              />
            </Stack>
          )}
        </Box>

        {/* ── In-feed Banner Promotion ───────────────────────────────────────── */}
        <Box
          sx={{
            borderRadius: '16px',
            p: { xs: 3, md: 4 },
            mb: 6,
            background: 'linear-gradient(135deg, #0f172a 0%, #1e1b4b 100%)',
            color: '#ffffff',
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 3,
            boxShadow: '0 16px 40px rgba(15, 23, 42, 0.18)',
          }}
        >
          <Box>
            <Typography variant=\"h5\" fontWeight={800} sx={{ mb: 0.5 }}>
              Khám phá 10.000+ việc làm đang tuyển dụng
            </Typography>
            <Typography variant=\"body2\" sx={{ color: 'rgba(255,255,255,0.80)' }}>
              Ứng tuyển nhanh chóng, kết nối trực tiếp với nhà tuyển dụng hàng đầu.
            </Typography>
          </Box>
          <Button
            component={Link}
            href={jobsHref}
            variant=\"contained\"
            endIcon={<ArrowForwardIcon />}
            sx={{
              bgcolor: '#e11d48',
              color: '#ffffff',
              fontWeight: 800,
              px: 3,
              py: 1.25,
              borderRadius: '12px',
              whiteSpace: 'nowrap',
              '&:hover': { bgcolor: '#be123c' },
            }}
          >
            Tìm việc ngay
          </Button>
        </Box>

        {/* ── Popular Keywords Tag Cloud ────────────────────────────────────── */}
        <Card elevation={0} sx={{ borderRadius: 3, border: '1px solid #e2e8f0', p: 3, bgcolor: '#ffffff' }}>
          <Typography variant=\"h6\" fontWeight={800} color=\"#0f172a\" sx={{ mb: 2 }}>
            Từ khoá nổi bật
          </Typography>
          <Stack direction=\"row\" spacing={1} flexWrap=\"wrap\" sx={{ gap: 1 }}>
            {popularKeywords.map((item) => {
              const labelText = item;
              const itemKey = `kw-${item}`;
              const searchHref = `${jobsHref}?kw=${encodeURIComponent(item)}`;

              return (
                <Chip
                  key={itemKey}
                  label={labelText}
                  clickable
                  component={Link}
                  href={searchHref}
                  sx={{
                    bgcolor: '#f1f5f9',
                    color: '#475569',
                    fontWeight: 600,
                    fontSize: '0.8rem',
                    borderRadius: '8px',
                    border: '1px solid #e2e8f0',
                    '&:hover': {
                      bgcolor: '#ffffff',
                      color: '#e11d48',
                      borderColor: '#e11d48',
                    },
                  }}
                />
              );
            })}
          </Stack>
        </Card>
      </Container>
    </Box>
  );
};

