                />
                {categories.slice(0, 5).map((cat) => {
                  const isSelected = activeCategorySlug === cat.slug;
                  return (
                    <Chip
                      key={cat.id}
                      label={cat.name.toUpperCase()}
                      clickable
                      onClick={() => handleSelectCategory(cat.slug)}
